  [220345] = { "さまざまな強力な血の儀式について概説した書物。どんな図書館の蔵書としても物議を醸す一冊。", 0xd9cba5ad, "u" },
  [220346] = { "震える手で書きなぐられた、判読できないメモと図で埋め尽くされている。それでも図書館の蔵書としてはまずまずの一冊かもしれない。", 0xe3ef334c, "u" },
  [220347] = { "ページの上で文字が泳ぎ、読もうとしても読めない。どんな図書館の蔵書としても不可解な一冊。", 0xfbfc8bcb, "u" },
  [220348] = { "上品なHighborne社会における初歩的な魔法の役割についての手引き。どんな図書館の蔵書にもふさわしい一冊。", 0x4cbbb1a5, "u" },
  [220349] = { "最も壊滅的な災害以外なら何にでも耐えられる、頑丈な建築技術。どんな図書館の蔵書にもふさわしい一冊。", 0x0f4f4783, "u" },
  [220350] = { "さまざまな毒素と毒液の精神を変容させる性質についての覚え書き。どんな図書館の蔵書にもふさわしい一冊。", 0x9a63e401, "u" },
  [220351] = { "シャーマンが元素の霊を見られるようにします。\n濁った調合薬。本来なら見分けのつく魔法に、不正に得た奇妙な力が混じっている。", 0x30414fb1, "u" },
  [220352] = { "冶金、露天掘り、重工業に魔法を応用するドワーフの技術。陰鬱ではあるが、どんな図書館の蔵書としても有益な一冊。", 0x5e1acf71, "u" },
  [220353] = { "戦前に編まれた呪文と秘術理論の集成。その大半は現代ではもう使われていない。どんな図書館の蔵書にもふさわしい一冊。", 0xc9653d3e, "u" },
